target.command:
cd /home/john/mynotes/deterministic_equidistribution_theory/c_suite/out_kappa
echo "=== residue-only uniform gap kappa_Q = 1 - MAX_chi (rho_chi/rho_0), full group ==="
echo "    (worst character governs the gap; annealed predicts worst = lowest freq k=1)"
printf "%6s %5s | %-22s | %-22s | %10s\n" "Q" "phi" "s=0: kappa (argmax k)" "s=1: kappa (argmax k)" "ann 1-|p^(1/phi)|"
grep -v '^#' fourier_comparison.csv | grep -v '^Q,' | awk -F, '
  { Q=$1; k=$2; xi=$3; g0=$5; g1=$6;
    if(!(Q in m0)||g0>m0[Q]){m0[Q]=g0; a0[Q]=k}
    if(!(Q in m1)||g1>m1[Q]){m1[Q]=g1; a1[Q]=k}
    phi[Q]=Q-Q/3 }
  END{ split("9 27 81 243 729 2187",QS," ");
    pi=3.14159265358979323846;
    for(i=1;i<=6;i++){ Q=QS[i]; ph=phi[Q]; xi1=1.0/ph;
      ann=1-1/sqrt(5-4*cos(2*pi*xi1));
      printf "%6s %5d | %.5f (k=%-4s)        | %.5f (k=%-4s)        | %.6f\n",
        Q,ph,1-m0[Q],a0[Q],1-m1[Q],a1[Q],ann } }'
